#!/bin/sh
# Minio bucket creation script
# Generated by dock-local

set -e

echo "Minio: Creating buckets..."

mc alias set local http://localhost:9000 "${MINIO_ROOT_USER}" "${MINIO_ROOT_PASSWORD}"

{{#each buckets}}
echo "Creating bucket: {{this}}"
mc mb --ignore-existing local/{{this}}
mc anonymous set download local/{{this}}
{{/each}}

{{#unless buckets}}
echo "No buckets detected to create"
{{/unless}}

echo "Minio initialization complete"
